import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;import java.io.PrintWriter;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int t = Integer.parseInt(st.nextToken());int[] a = new int[n];st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());}int left = 0;int currentSum = 0;int maxBooks = 0;for (int right = 0; right < n; right++) {currentSum += a[right];while (currentSum > t && left <= right) {currentSum -= a[left];left++;}maxBooks = Math.max(maxBooks, right - left + 1);}PrintWriter out = new PrintWriter(System.out);out.println(maxBooks);out.flush();out.close();}}